// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 100 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // General rule: a successful Put always credits the sender's balance by msg.value.
        (uint256 unlockTime, uint256 balance) = c.Acc(actor);
        unlockTime;
        assertTrue(balance >= amount && balance == amount);
    }
}
